{
  "components": [
    {
      "description": "HTTP handlers for browsing/searching the catalog and checkout flow.",
      "id": "Presentation",
      "name": "Presentation",
      "contained_modules:": [
        "bookshop",
        "bookshop.api",
        "bookshop.api.catalog_routes",
        "bookshop.api.checkout_routes"
      ]
    },
    {
      "description": "Use-case services that orchestrate domain logic with infrastructure adapters.",
      "id": "Application",
      "name": "Application",
      "contained_modules:": [
        "bookshop.application",
        "bookshop.application.checkout",
        "bookshop.application.inventory"
      ]
    },
    {
      "description": "Core business model including books, orders, pricing rules, and catalog aggregate.",
      "id": "Domain",
      "name": "Domain",
      "contained_modules:": [
        "bookshop.domain",
        "bookshop.domain.book",
        "bookshop.domain.catalog",
        "bookshop.domain.order",
        "bookshop.domain.pricing"
      ]
    },
    {
      "description": "In-memory persistence adapters for books and orders, and a fake payment gateway.",
      "id": "Infrastructure",
      "name": "Infrastructure",
      "contained_modules:": [
        "bookshop.infrastructure",
        "bookshop.infrastructure.book_repository",
        "bookshop.infrastructure.order_repository",
        "bookshop.infrastructure.payment_gateway"
      ]
    }
  ],
  "relations": [
